import{_ as e,o,c as s,a2 as a}from"./chunks/framework.RycU2wFZ.js";const p=JSON.parse('{"title":"稳定币基础，为什么选 USDC","description":"","frontmatter":{},"headers":[],"relativePath":"zh/learn/02-agent-payments/stablecoins-and-usdc.md","filePath":"zh/learn/02-agent-payments/stablecoins-and-usdc.md","lastUpdated":1792590840000}'),n={name:"zh/learn/02-agent-payments/stablecoins-and-usdc.md"};function r(i,t,d,l,g,h){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="稳定币基础-为什么选-usdc" tabindex="-1">稳定币基础，为什么选 USDC <a class="header-anchor" href="#稳定币基础-为什么选-usdc" aria-label="Permalink to &quot;稳定币基础，为什么选 USDC&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：稳定币是将价格与法定货币（通常是美元）1:1 锚定的链上数字代币。当 AI Agent 需要在开放互联网中进行高频微额结算时，它必须依赖一种“价格稳定、无需开户、可编程且全球可用”的基础资产，而 USDC 正是目前最契合的工业级标准。</p></blockquote><p><strong>本篇你会了解</strong>：</p><ul><li>为什么 ETH 等波动性加密资产无法作为 Agent 的计价与结算货币</li><li>稳定币如何完美契合 Agent 自动化的五大底层诉求</li><li>为什么选 USDC 的核心技术驱动力（原生支持 EIP-3009 离线授权）</li><li>金融工程铁律：为什么在任何情况下都<strong>绝不使用浮点数（Float）</strong></li><li>AgentPay 当前的测试网边界与安全提示</li></ul><hr><h2 id="_1-稳定币是什么-告别加密货币的价格坐过山车" tabindex="-1">1. 稳定币是什么：告别加密货币的价格坐过山车 <a class="header-anchor" href="#_1-稳定币是什么-告别加密货币的价格坐过山车" aria-label="Permalink to &quot;1. 稳定币是什么：告别加密货币的价格坐过山车&quot;">​</a></h2><p>如果让一个数据检索 Agent 用传统加密货币（如 ETH 或 BTC）去购买 API 服务，会遇到一个荒诞的经济学难题：</p><ul><li>开发者为某项搜索服务标价：<code>&quot;本次调用 0.0001 ETH&quot;</code>。</li><li>然而加密市场转瞬即变，由于行情波动，今天这笔调用价值 30 美分，明天可能暴涨到 60 美分，后天又跌到 10 美分。</li><li><strong>这种剧烈的价格波动彻底摧毁了 Agent 的自动化预算规划与成本控制能力</strong>——Agent 根本无法在不确定未来支出的情况下做出理性的业务决策。</li></ul><p>**稳定币（Stablecoin）**应运而生。它通过将代币价值锚定在法币（美元）上，解决了这一痛点：以行业主流的 USDC 为例：</p><ul><li><strong>1 USDC 长期紧密锚定 1 美元</strong>（1 USDC ≈ 1 USD）；</li><li>发行方（Circle）通过持有等额且透明的美元现金及短债储备资产作为背书来维持刚性兑付；</li><li>它本质上是以智能合约代币（通常遵循 ERC-20 标准）的形式运行在高性能区块链上，支持 7×24 小时的全球实时划转。</li></ul><blockquote><p>⚠️ <strong>风险警示</strong>：“稳定”是设计目标与历史常态，而非绝对的数学保证。任何稳定币都存在发行方信誉、储备金透明度与底层监管风险。因此，<strong>AgentPay 在现阶段严格限定于测试网环境与测试代币，绝不涉及任何真实资产</strong>。</p></blockquote><hr><h2 id="_2-为什么-agent-支付偏爱稳定币" tabindex="-1">2. 为什么 Agent 支付偏爱稳定币？ <a class="header-anchor" href="#_2-为什么-agent-支付偏爱稳定币" aria-label="Permalink to &quot;2. 为什么 Agent 支付偏爱稳定币？&quot;">​</a></h2><p>我们将上一篇提到的 Agent 支付需求与稳定币的特性做一次全景式对位：</p><table tabindex="0"><thead><tr><th>Agent 核心需求</th><th>稳定币如何完美满足</th></tr></thead><tbody><tr><td><strong>价格可预期（Predictable Pricing）</strong></td><td>标价 <code>0.05 USDC</code> 在任何时候都约等于 5 美分，卖方可以清晰定价，买方 Agent 可以精准做财务预算。</td></tr><tr><td><strong>无需开户（Permissionless）</strong></td><td>钱包地址即身份，无需人类去平台注册、做 KYC 或绑定信用卡，Agent 发现陌生服务即可直接发起支付。</td></tr><tr><td><strong>高度可编程（Programmability）</strong></td><td>金额、收款方、最晚有效期等约束都可以写进密码学签名授权里，由智能合约强制执行，无法篡改。</td></tr><tr><td><strong>全球无缝可用（Global Reach）</strong></td><td>不受传统银行营业时间、跨境清算延迟、外汇管制或高额电汇费的限制，秒级到账。</td></tr><tr><td><strong>易于硬编码策略约束（Budgeting）</strong></td><td>预算上限可以表示为一个干净的整数（如“每天限额 5,000,000 最小单位”），极其便于风控引擎通过策略进行强制拦截。</td></tr></tbody></table><hr><h2 id="_3-为什么偏偏是-usdc-——-揭秘-eip-3009" tabindex="-1">3. 为什么偏偏是 USDC？—— 揭秘 EIP-3009 <a class="header-anchor" href="#_3-为什么偏偏是-usdc-——-揭秘-eip-3009" aria-label="Permalink to &quot;3. 为什么偏偏是 USDC？—— 揭秘 EIP-3009&quot;">​</a></h2><p>在加密世界里有成百上千种稳定币（如 USDT、DAI、USDC 等），为什么 AgentPay 架构首选 USDC？</p><p>选型的核心决定因素不是品牌效应，而是<strong>底层技术是否原生支持免 Gas 授权协议（EIP-3009）</strong>：</p><ul><li><strong>原生 <code>transferWithAuthorization</code></strong>：USDC 在主流 EVM 链上原生实现了 EIP-3009 标准。它允许“持币人（买方 Agent）在本地用私钥进行离线签名，然后将签名交由第三方（卖方或 Facilitator）代为提交并完成转账”。</li><li><strong>“免持有 Gas 代币”的极致体验</strong>：这意味着<strong>买方 Agent 钱包里完全不需要存 ETH 等原生 Gas 费代币</strong>。如果没有这一特性，Agent 在调用一个陌生服务前，还得先去买一点 ETH 来交手续费，自动化体验将被彻底破坏。</li><li><strong>强大的跨链与工具生态</strong>：USDC 在各大主流 L2 网络（如 Arbitrum、Base 等）上均由 Circle 官方直接部署，拥有深厚的流动性与高度成熟的开发者工具链。</li><li><strong>友好的测试网基础设施</strong>：官方提供了便捷的测试网水龙头（Faucet），开发者可以零成本获取测试 USDC 来验证工作流。</li></ul><blockquote><p><strong>架构包容性说明</strong>：x402 协议和 AgentPay 核心框架在设计上是<strong>资产与网络无关的（Asset &amp; Chain Agnostic）</strong>。协议本身也支持其他合规资产。但在 v0.1.x 阶段，我们将精力聚焦于“USDC + EIP-3009”这条最成熟的工业级路径，把其他资产的扩展留给后续版本。</p></blockquote><hr><h2 id="_4-铁律-为什么在金额处理中绝对禁止使用浮点数" tabindex="-1">4. 铁律：为什么在金额处理中绝对禁止使用浮点数？ <a class="header-anchor" href="#_4-铁律-为什么在金额处理中绝对禁止使用浮点数" aria-label="Permalink to &quot;4. 铁律：为什么在金额处理中绝对禁止使用浮点数？&quot;">​</a></h2><p>在区块链和金融系统的代码实现中，有一个常年血流成河的坑：<strong>浮点数精度误差</strong>。</p><p>USDC 具有 <strong>6 位小数（<code>decimals: 6</code>）</strong>。这意味着在底层账本和接口传输中，我们绝不传递带有小数点的浮点数（如 <code>0.1</code>），而是将其换算为<strong>整数最小单位（Base Units）</strong>：</p><table tabindex="0"><thead><tr><th>人类可读展示金额</th><th>整数最小单位（Base Units）</th><th>备注</th></tr></thead><tbody><tr><td><code>1 USDC</code></td><td><code>1_000_000</code></td><td>10 的 6 次方</td></tr><tr><td><code>0.1 USDC</code></td><td><code>100_000</code></td><td>10 美分</td></tr><tr><td><code>0.001 USDC</code></td><td><code>1_000</code></td><td>1 美分的一小部分</td></tr><tr><td><code>0.000001 USDC</code></td><td><code>1</code></td><td>最小可分单位（1 Micro-USDC）</td></tr></tbody></table><h3 id="为什么必须强制用整数" tabindex="-1">为什么必须强制用整数？ <a class="header-anchor" href="#为什么必须强制用整数" aria-label="Permalink to &quot;为什么必须强制用整数？&quot;">​</a></h3><p>看一个经典的计算机底层笑话（Python / JavaScript 浮点陷阱）：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.30000000000000004</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 产生了意料之外的微小尾数误差！</span></span></code></pre></div><p>在普通的网页展示中，多出四位小数可能无关紧要；但在<strong>金融清算、预算限额与密码学签名</strong>中，哪怕 <code>0.000001</code> 的偏差也会导致：</p><ol><li>签名验签时计算出的哈希值（Hash）与链上合约预期不符，直接导致支付失败。</li><li>在累加多笔微交易预算时，误差累积导致对账不平（Accounting Mismatch）。</li></ol><p>因此，AgentPay 制定了不可动摇的<strong>安全红线</strong>：</p><ul><li><strong>协议通信与签名载荷中</strong>：金额一律使用<strong>字符串包裹的整数</strong>（如 <code>&quot;100000&quot;</code>）。</li><li><strong>本地数据库存储中</strong>：SQLite 的金额字段必须强制加上 <code>CHECK (typeof(col) = &#39;integer&#39;)</code> 约束，PostgreSQL 必须使用 <code>BIGINT</code> 类型。</li><li><strong>展示层（UI）</strong>：只有在最终呈现给人类用户阅读的浏览器界面上，才允许除以 $10^6$ 换算为“0.1 USDC”进行展示。</li></ul><hr><h2 id="_5-测试网-vs-主网环境说明" tabindex="-1">5. 测试网 vs 主网环境说明 <a class="header-anchor" href="#_5-测试网-vs-主网环境说明" aria-label="Permalink to &quot;5. 测试网 vs 主网环境说明&quot;">​</a></h2><p>在动手开发或测试 AgentPay 相关的集成代码时，必须时刻明确当前运行的环境边界：</p><table tabindex="0"><thead><tr><th>维度</th><th>测试网环境（如 Arbitrum Sepolia）</th><th>生产主网环境（Mainnet）</th></tr></thead><tbody><tr><td><strong>代币资产属性</strong></td><td><strong>无任何真实金融价值</strong>，可通过官方水龙头免费领取。</td><td><strong>真实真金白银</strong>（Real Capital）。</td></tr><tr><td><strong>主要应用场景</strong></td><td>开发调试、集成测试、端到端 Demo 演示。</td><td>线上真实商业生产环境。</td></tr><tr><td><strong>AgentPay 当前状态</strong></td><td><strong>✅ 官方完全支持并推荐用于测试</strong>。</td><td><strong>❌ 尚未完成全面审计，严禁用于生产资金</strong>。</td></tr></tbody></table><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>资产选择</strong>：稳定币为 Agent 提供了价格稳定、可预期、无需开户且高度可编程的完美结算载体。</li><li><strong>核心依赖</strong>：选择 USDC 的根本原因在于其原生支持 EIP-3009 (<code>transferWithAuthorization</code>)，使买方 Agent 在离线签名时完全无需持有或消耗原生 Gas 代币。</li><li><strong>安全铁律</strong>：金额在任何代码、协议载荷与数据库中都必须以**整数最小单位（Base Units）**存储和传输，严禁使用任何形式的浮点数，以彻底消灭精度误差。</li><li><strong>当前边界</strong>：现阶段所有实验与开发均锚定在测试网环境，严禁在生产主网上直接裸奔使用。</li></ul><p><strong>下一篇</strong>：<a href="./gasless-eip-3009">gasless-eip-3009.md</a> —— EIP-712 与 EIP-3009 深度解析：为什么 Agent 可以真正做到“零 Gas 负担”？</p>`,41)])])}const u=e(n,[["render",r]]);export{p as __pageData,u as default};
